### LogicalPosition and LogicalSize classes

Source: https://github.com/tauri-apps/tauri-docs/blob/v2/packages/tauri/packages/api/src/dpi.ts

Type-safe pixel value classes that make the unit explicit. LogicalPosition and LogicalSize represent coordinates/dimensions in logical (DPI-scaled) pixels. They include a toPhysical method for conversion using a scaleFactor. Both serialize automatically for IPC via a SERIALIZE_TO_IPC_FN symbol that strips the type wrapper.

```typescript
class LogicalSize {
  readonly type = 'Logical'
  width: number
  height: number

  constructor(width: number, height: number)
  constructor(object: { Logical: { width: number; height: number } })
  constructor(object: { width: number; height: number })
  constructor(...args: [number, number] | [{ width: number; height: number }] | [{ Logical: { width: number; height: number } }]) {
    if (args.length === 1) {
      if ('Logical' in args[0]) {
        this.width = args[0].Logical.width
        this.height = args[0].Logical.height
      } else {
        this.width = args[0].width
        this.height = args[0].height
      }
    } else {
      this.width = args[0]
      this.height = args[1]
    }
  }

  toPhysical(scaleFactor: number): PhysicalSize {
    return new PhysicalSize(this.width * scaleFactor, this.height * scaleFactor)
  }
}

class LogicalPosition {
  readonly type = 'Logical'
  x: number
  y: number

  constructor(x: number, y: number)
  constructor(object: { Logical: { x: number; y: number } })
  constructor(object: { x: number; y: number })
  constructor(...args: [number, number] | [{ x: number; y: number }] | [{ Logical: { x: number; y: number } }]) {
    if (args.length === 1) {
      if ('Logical' in args[0]) {
        this.x = args[0].Logical.x
        this.y = args[0].Logical.y
      } else {
        this.x = args[0].x
        this.y = args[0].y
      }
    } else {
      this.x = args[0]
      this.y = args[1]
    }
  }

  toPhysical(scaleFactor: number): PhysicalPosition {
    return new PhysicalPosition(this.x * scaleFactor, this.y * scaleFactor)
  }
}
```

